def status_check(altitude):
    if altitude > 100:
        print("Too high")
    print("Check complete")

# Convert seconds of flight time into minutes
def to_minutes(seconds):
    return seconds / 60  # division, not floor division

distances = [10, 20, 30]
for d in distances:
    print("Fly forward", d, "cm")

altitudes = [50, 80, 60]
for i in range(len(altitudes)):
    print("Waypoint", i, "is at", altitudes[i], "cm")

def battery_status(level):
    if level > 60:
        return "good"
    elif level > 20:
        return "low"
    else:
        return "critical"

print(battery_status(15))   # critical

def safe_to_launch(battery, is_raining):
    if is_raining:
        return False
    if battery < 10:
        return False
    return True

print(safe_to_launch(50, False))   # True
